{
  "intents": {
    "ovos_ollama_intent_pipeline": {
      "model": "llama3",
      "base_url": "http://192.168.1.200:11434",
      "temperature": 0.0,
      "timeout": 5,
      "fuzzy": true,
      "min_words": 2,
      "ignore_labels": []
    }
  }
}

